const d=[{id:"T01",title:"Dai, Milkman & Riis · 2014 · The fresh-start effect",url:"https://faculty.wharton.upenn.edu/wp-content/uploads/2014/06/Dai_Fresh_Start_2014_Mgmt_Sci.pdf",type:"research",finding:"Three archival datasets showed increases in goal initiation around calendar landmarks, including diet searches, university gym visits, and commitment contracts.",limitation:"Observational initiation measures do not establish causation, sustained change, or the effect of declaring an arbitrary date a beginning."},{id:"T02",title:"Dai, Milkman & Riis · 2015 · Temporal landmarks and goal initiation",url:"https://anderson-review.ucla.edu/wp-content/uploads/2021/03/Dai-Milkman-Riis_2015_TemporalLandmarks_APS_0956797615605818.pdf",type:"research",finding:"Among 165 online adults, 25.61% chose a March 20 reminder when framed as spring’s beginning versus 7.23% when framed as the third Thursday.",limitation:"This contrast measured reminder selection, not actual action or lasting change. A personally declared starting day is an ODA adaptation."},{id:"T03",title:"Gollwitzer & Sheeran · 2006 · Implementation intentions and goal achievement",url:"https://doi.org/10.1016/S0065-2601(06)38002-1",type:"research",finding:"Across 94 independent tests with 8,461 participants, specific if–then plans improved goal attainment on average: d = 0.65, 95% CI [0.60, 0.70].",limitation:"Varied settings and older methods limit generalization. The effect is not a 65% success increase, and this brief ODA planner was not tested."},{id:"T04",title:"Wang, Wang & Gai · 2021 · Mental contrasting with implementation intentions",url:"https://pmc.ncbi.nlm.nih.gov/articles/PMC8149892/",type:"research",finding:"A meta-analysis of 21 articles and 24 effects, involving 15,907 participants, found a modest average goal-attainment benefit: g = 0.336, 95% CI [0.229, 0.443].",limitation:"Results varied, with possible publication bias. Two large online samples dominate the participant total. Imagery does not attract outcomes, and ODA’s exercise was not tested."},{id:"T05",title:"Harkin et al. · 2016 · Monitoring goal progress",url:"https://pubmed.ncbi.nlm.nih.gov/26479070/",type:"research",finding:"Across 138 randomized studies with 19,951 participants, progress-monitoring interventions improved goal attainment on average: d = 0.40, 95% CI [0.32, 0.48].",limitation:"Goals and methods varied. Physical recording and reporting were associated with larger effects in moderator analyses; public disclosure is not necessary and this ODA ledger was not tested."},{id:"T06",title:"Lally et al. · 2010 · Modeling habit formation",url:"https://onlinelibrary.wiley.com/doi/10.1002/ejsp.674",type:"research",finding:"An 84-day observational study followed 96 volunteers. Among 39 good-fitting curves, the model estimated 18–254 days to 95% of each automaticity asymptote, with a median of 66.",limitation:"These were modeled estimates, not observed completion dates. Self-reported everyday health behaviors do not establish a universal timeline or a two-missed-opportunity threshold."},{id:"T07",title:"Singh et al. · 2024 · Time to form a habit",url:"https://doi.org/10.3390/healthcare12232488",type:"research",finding:"A review of 20 health-behavior studies with 2,601 participants found highly variable formation-time estimates. Only four studies supplied timing estimates; individual estimates ranged from 4 to 335 days.",limitation:"Eleven studies had high bias risk. Timing definitions differed. Pre–post habit-strength change is not a controlled treatment effect or a personal deadline."},{id:"T08",title:"Wood & Rünger · 2016 · Psychology of habit",url:"https://dornsife.usc.edu/wendy-wood/wp-content/uploads/sites/183/2023/10/wood.runger.2016.pdf",type:"research",finding:"This review describes how repeating responses in recurring contexts can make behavior cue-driven, while deliberate goals and habits can work together.",limitation:"An integrative narrative review, not a new trial or pooled effect. It does not show that object placement removes motivation needs or that every complex goal becomes automatic."},{id:"T09",title:"Bandura · 1977 · Self-efficacy theory",url:"https://dradamvolungis.com/wp-content/uploads/2011/06/self-efficacy-unifying-theory-of-behavioral-change-bandura-1977.pdf",type:"research",finding:"Bandura’s theory identifies personal accomplishment, watching others, encouragement, and bodily states as sources of expectations about performing a particular behavior, with emphasis on personal mastery.",limitation:"A theory integrating earlier research, not a new trial. It does not prove that every small act raises confidence or establishes broad capability."},{id:"T11",title:"Scullin et al. · 2018 · Bedtime task-list writing",url:"https://pmc.ncbi.nlm.nih.gov/articles/PMC5758411/",type:"research",finding:"In one laboratory night, 57 healthy adults aged 18–30 wrote future tasks or completed activities on paper for five minutes. Mean sleep-onset latency was 15.82 versus 25.09 minutes.",limitation:"Another writing task was the comparator. No significant increase in total sleep or long-term insomnia benefit was established. Spoken suggestions and ODA’s brief review were not tested."},{id:"T12",title:"Wohl, Pychyl & Bennett · 2010 · Self-forgiveness and exam procrastination",url:"https://doi.org/10.1016/j.paid.2010.01.029",type:"research",finding:"Among 119 first-year students, greater self-forgiveness for procrastinating before one midterm was associated with less procrastination before the next.",limitation:"Observational measurements in one course do not establish causation. The abstract does not verify an effect coefficient or a benefit from a scripted sentence."},{id:"T15",title:"Oettingen et al. · 2015 · Mental contrasting and time management",url:"https://www.socmot.uni-konstanz.de/sites/default/files/Oettingen_et_al-2015-European_Journal_of_Social_Psychology_0.pdf",type:"research",finding:"Study 1 randomized 84 German undergraduates. The combined exercise group scheduled more hours than two controls; the planned contrast was significant, while the overall condition test was p = .057.",limitation:"Scheduled hours were an intention measure, not hours worked or completed projects. The study does not validate ODA’s short action and next-day review."},{id:"T17",title:"James Clear · The two-minute rule",url:"https://jamesclear.com/how-to-stop-procrastinating",type:"technique",finding:"Clear suggests shrinking a new behavior to a brief entry action. This is practitioner guidance for choosing an approachable start.",limitation:"The precise two-minute dose is not established as optimal by controlled research. Preparation is not the same as completing a useful unit of the intended behavior."},{id:"bandura-self-efficacy",title:"Bandura · 1977 · Self-efficacy theory",url:"https://dradamvolungis.com/wp-content/uploads/2011/06/self-efficacy-unifying-theory-of-behavioral-change-bandura-1977.pdf",type:"research",finding:"Bandura’s theory identifies personal accomplishment, watching others, encouragement, and bodily states as sources of expectations about performing a particular behavior, with emphasis on personal mastery.",limitation:"A theory integrating earlier research, not a new trial. It does not prove that every small act raises confidence or establishes broad capability."},{id:"habits",title:"Lally et al. · 2010 · Modeling habit formation",url:"https://onlinelibrary.wiley.com/doi/10.1002/ejsp.674",type:"research",finding:"An 84-day observational study followed 96 volunteers. Among 39 good-fitting curves, the model estimated 18–254 days to 95% of each automaticity asymptote, with a median of 66.",limitation:"These were modeled estimates, not observed completion dates. Self-reported everyday health behaviors do not establish a universal timeline or a two-missed-opportunity threshold."},{id:"oettingen-woop-method",title:"Gabriele Oettingen · WOOP",url:"https://woopmylife.org/en/home",type:"technique",finding:"WOOP combines a wish, desired outcome, inner obstacle, and if–then plan. Related research supports planning on average, with varied results.",limitation:"The developer’s site is not an independent evaluation. MCII findings do not validate every version of the method or make external constraints a mindset failure."}],r=[{schemaVersion:2,revision:2,id:"turning-day-1",courseId:"turning-day",locale:"en",title:"Still waiting for Monday? Make one real start",goal:"Take one useful unit toward a chosen direction, then schedule a next opportunity.",minutes:{learning:6,suggestedAction:2,review:2},direction:{hook:"What keeps landing on next Monday’s list instead of today’s life?",reason:{id:"turning-day-1-reason",label:"What deserves two minutes, and what can wait?",kind:"text",maxLength:160,optional:!0,suggestions:["Make room for creativity","Practice before another week passes","Protect time for what matters"]},why:{id:"turning-day-1-why",label:"What deserves two minutes, and what can wait?",kind:"text",maxLength:300,optional:!0}},idea:{paragraphs:["A date can influence a starting choice without showing follow-through. In one experiment, the same March date attracted more reminder choices when called spring’s beginning. The study did not show whether people acted on those reminders.","Use the opening for one small act in your chosen direction. Draw an object, write a usable sentence, or read a needed paragraph. Choosing a date is preparation. Do the act, record it, and name your next cue. Carry this experiment through the course."],example:{title:"Dana’s first drawing",text:"Dana keeps postponing drawing until Monday. On Wednesday, after tea at her kitchen table, she sketches the mug for two minutes. The handle looks crooked. She records one sketch, then chooses tomorrow’s tea as her next cue. Naming Wednesday a beginning helped her choose; it did not improve her drawing."}},move:{invitation:"Choose drawing, writing, or reading only if it serves your direction.",instructions:["Check the example fits your direction before filling a blank plan.","Try your chosen act, then record it here."],prompts:[],suggestions:{action:["Draw one everyday object","Write one usable sentence","Read one needed paragraph"],minimum:["Finish one small sketch","Write one useful sentence","Read one complete paragraph"],when:[{label:"Today",daysFromToday:0},{label:"Tomorrow",daysFromToday:1}],cue:["After my next cup of tea","After my next meal"],place:["At my kitchen table","At my usual work surface","In my accessible reading space"],minutes:[2,1,5],fallback:["Use a smaller object or adapted tools","Dictate one sentence if typing is difficult","Use accessible text or read aloud"],observation:["The sketch I finished","The usable sentence I wrote","The paragraph I read"],bundles:[{action:"Draw one everyday object",minimum:"Finish one small sketch",cue:"After my next cup of tea",place:"At my kitchen table",fallback:"Use a smaller object or adapted tools",observation:"The sketch I finished",minutes:2},{action:"Write one usable sentence",minimum:"Write one useful sentence",cue:"After my next meal",place:"At my usual work surface",fallback:"Dictate one sentence if typing is difficult",observation:"The usable sentence I wrote",minutes:2},{action:"Read one needed paragraph",minimum:"Read one complete paragraph",cue:"After my next meal",place:"In my accessible reading space",fallback:"Use accessible text or read aloud",observation:"The paragraph I read",minutes:2}]},suggested:{action:"Draw one everyday object",minimum:"Finish one small sketch",minutes:2,cueHint:"After my next cup of tea",placeHint:"At my kitchen table",obstacleHint:"My available time or tools change",fallbackHint:"Use a smaller object or adapted tools",observationHint:"The sketch I finished",requiresChoice:!0},accessibleAlternative:"Type, dictate, use adapted tools, or ask for assistance with your chosen unit.",stopRule:"Choose a safe task. Adapt or pause if health, care, or access needs take priority."},result:{question:"What actually happened with your chosen minimum?",observationPrompt:"What did you do, and what got in the way?"},judgment:{primary:{id:"turning-day-1-decision",scenario:"Dana has two free minutes and paper at her kitchen table. She wants to draw but usually waits for Monday.",question:"Which move fits these facts?",options:[{id:"draw-now",text:"Sketch the nearby mug now, record the sketch, and choose another feasible opportunity tomorrow.",feedback:"This uses an available opening for actual drawing. The sketch can be rough. Record the unit you completed, then give the same experiment its next cue."},{id:"schedule-course",text:"Use the two minutes to schedule a full drawing course for next week.",feedback:"A course might help later, but Dana already has enough time and materials for one sketch. Scheduling makes a plan; drawing tests her chosen direction today."},{id:"choose-supplies",text:"Compare beginner drawing supplies, then decide which object will be easiest to draw.",feedback:"Suitable tools matter when they are missing. Dana already has paper and a usable object. More selection uses this opening without producing a drawing attempt."}],bestOptionId:"draw-now"}},carry:{takeaway:"A beginning becomes evidence when you do one useful unit.",followUp:{questionId:"turning-day-1-return",question:"Did your useful unit happen when your chosen cue arrived?",observationPrompt:"What did you actually do or notice?",adjustmentPrompt:"What should stay or change at the next opportunity?"}},goDeeper:{sections:[{heading:"A reminder is not an attempt",paragraphs:["Dai, Milkman, and Riis studied fresh starts through three archival datasets in 2014 [T01]. Diet searches, university gym attendance, and new commitment contracts increased around some calendar landmarks. These are different initiation measures. They do not establish that the landmark caused the change or that participants sustained their goals.","In a later experiment, 165 online adults chose between dates for a goal reminder [T02]. For March 20, 25.61% chose the reminder when the date was called spring’s beginning. The figure was 7.23% when it was called the third Thursday. That contrast concerns selecting a reminder. It does not tell us who acted afterward.","Calling today your beginning is an optional ODA framing device. The course does not claim that naming an arbitrary date reproduces these findings. Your record starts with what you actually do."]},{heading:"Give the opening a behavior",paragraphs:["An if–then plan connects a recognizable situation with a response chosen beforehand. Gollwitzer and Sheeran reviewed 94 independent tests with 8,461 participants [T03]. Such plans improved goal attainment on average across those settings. Different tasks, populations, and research methods make that average a poor personal forecast. This short ODA lesson was not tested in the review.","For this experiment, choose a useful unit that serves your direction. “After tea at the kitchen table, sketch one object” names a cue, a place, and an act. Putting out paper is preparation. Making a sketch is drawing practice. Either can matter, but record the one you actually did.","Your direction can serve care, recovery, connection, or learning. If the available setting cannot support a safe act, choose a feasible later opening or support. A calendar label cannot remove a real constraint."]}],sourceIds:["T01","T02","T03"]}},{schemaVersion:2,revision:2,id:"turning-day-2",courseId:"turning-day",locale:"en",title:"Your plan meets the couch. Prepare for it",goal:"Use one feasible response to a likely obstacle in your existing experiment.",minutes:{learning:6,suggestedAction:2,review:2},direction:{hook:"Where could your good plan collide with your actual afternoon?",reason:{id:"turning-day-2-reason",label:"What stopped your last try, and what can change?",kind:"text",maxLength:160,optional:!0,suggestions:["Cue arrived while I was working","Needed recovery after my shift","A tool was unavailable"]},why:{id:"turning-day-2-why",label:"What stopped your last try, and what can change?",kind:"text",maxLength:300,optional:!0}},idea:{paragraphs:["Keep your useful unit. Check what might block it. A reaction you can answer differs from missing childcare, equipment, safe space, or capacity. Change an infeasible plan rather than treating every barrier as a problem inside you.","Link an obstacle or opportunity to a feasible response: “After taking off my work coat, I sketch one object at the table.” Studies support specific plans on average, with varied results. Writing is preparation. Test your response, then record whether it was available and used."],example:{title:"Dana’s after-work cue",text:"Dana’s shifts end at different times, so 6 p.m. rarely fits her drawing plan. She chooses taking off her work coat as the cue. At the kitchen table, she sketches her keys before turning on a show. She finishes one rough sketch; on the following late shift, she needs rest instead."}},move:{invitation:"Keep your saved action and minimum. Change one observed obstacle or opportunity.",instructions:["Keep any cue that fits; edit If blocked for the barrier you saw.","No previous attempt? Choose a feasible opening for your same act."],prompts:[],suggestions:{action:["Draw one everyday object","Write one usable sentence","Read one needed paragraph"],minimum:["Finish one small sketch","Write one useful sentence","Read one complete paragraph"],when:[{label:"Today",daysFromToday:0},{label:"Tomorrow",daysFromToday:1}],cue:["After taking off my work coat","When my planned break begins","After my next meal"],place:["At my kitchen table","At my usual work surface","In my accessible reading space"],minutes:[2,1,5],fallback:["Rest; use tomorrow’s afternoon break","Rest; use tomorrow’s available work break","Rest; read after tomorrow’s meal"],observation:["Whether the cue and sketch happened","Whether the cue and sentence happened","Whether the cue and reading happened"],bundles:[{action:"Draw one everyday object",minimum:"Finish one small sketch",cue:"After taking off my work coat",place:"At my kitchen table",fallback:"Rest; use tomorrow’s afternoon break",observation:"Whether the cue and sketch happened",minutes:2},{action:"Write one usable sentence",minimum:"Write one useful sentence",cue:"When my planned break begins",place:"At my usual work surface",fallback:"Rest; use tomorrow’s available work break",observation:"Whether the cue and sentence happened",minutes:2},{action:"Read one needed paragraph",minimum:"Read one complete paragraph",cue:"After my next meal",place:"In my accessible reading space",fallback:"Rest; read after tomorrow’s meal",observation:"Whether the cue and reading happened",minutes:2}]},suggested:{action:"Draw one everyday object",minimum:"Finish one small sketch",minutes:2,cueHint:"After taking off my work coat",placeHint:"At my kitchen table",obstacleHint:"I need recovery after a shift",fallbackHint:"Rest; use tomorrow’s afternoon break",observationHint:"Whether the cue and sketch happened"},accessibleAlternative:"Type, dictate, use adapted tools, or ask for assistance with your chosen unit.",stopRule:"Do not push through exhaustion, danger, or missing access. Choose rest, support, or another opportunity."},result:{question:"What actually happened with your chosen minimum?",observationPrompt:"What did you do, and what got in the way?"},judgment:{primary:{id:"turning-day-2-workday-cue-decision",scenario:"Dana wants brief sketches on ordinary workdays. Her shifts change, so 6 p.m. often falls during work. Taking off her coat happens at home, where two minutes are usually available.",question:"Which plan fits workdays with less daily rescheduling?",options:[{id:"days-off-session",text:"Choose short sessions on days off, accepting fewer workday chances while protecting her energy.",feedback:"Days-off practice can protect recovery and may suit a different aim. Dana wants brief workday opportunities; the homecoming event offers them without having to predict each shift ending."},{id:"coat-cue",text:"After taking off her coat, sketch one object; choose rest or another feasible opening when exhausted.",feedback:"This uses a recognizable event and preserves recovery. Dana can test the same drawing unit without pretending the clock or a stronger reminder controls her shifts."},{id:"shift-calendar-alert",text:"Check her shift calendar daily and set a sketch alert thirty minutes after the expected finish.",feedback:"This can work when finish times hold. Changing shifts add alert upkeep and uncertainty. The homecoming event already signals an available setting; test it while keeping rest an option."}],bestOptionId:"coat-cue"}},carry:{takeaway:"Plan for the conditions you have, then test the response.",followUp:{questionId:"turning-day-2-return",question:"Did your cue occur, and was your planned response actually possible?",observationPrompt:"What did you actually do or notice?",adjustmentPrompt:"What should stay or change at the next opportunity?"}},goDeeper:{sections:[{heading:"An obstacle is not always inside you",paragraphs:["Mental contrasting pairs a desired outcome with the obstacle to reaching it. Adding an if–then response is often called MCII. Wang and colleagues reviewed 21 articles with 24 independent effects and 15,907 participants [T04]. They found a modest average benefit for goal attainment, with differences across studies and possible publication bias.","This approach can clarify that a wish needs adjustment. It does not establish that imagining an outcome attracts it, that every obstacle is an emotion, or that pushing harder is always appropriate. External conditions belong in the feasibility check. Money, disability access, workload, and care responsibilities cannot be reduced to reluctance.","ODA’s adaptation asks you to keep your chosen direction while testing one response. The response might be a smaller unit, a different opportunity, or a practical request. Record whether it was possible before judging whether it worked."]},{heading:"A planning result is still a plan",paragraphs:["In one primary time-management study, 84 German undergraduates were randomized to three conditions [T15]. The combined mental-contrasting and planning group scheduled more hours than the controls. The planned contrast was significant, while the overall condition test was p = .057. Scheduled hours were the outcome. The study did not establish how many hours participants actually worked.","Across a broader review, specific if–then plans improved goal attainment on average [T03]. There is no single tested timer length or universal daily dose across those experiments. ODA’s short response trial and next-day return are educational adaptations, not the original research protocol.","A useful observation separates three questions: did the cue appear, was the response available, and did you use it? If the obstacle never occurred, the fallback remains untested. If the response was impossible, change the conditions or the plan."]}],sourceIds:["T03","T04","T15"]}},{schemaVersion:2,revision:2,id:"turning-day-3",courseId:"turning-day",locale:"en",title:"“I never follow through” needs a fact check",goal:"Complete one useful unit of your existing experiment and describe exactly what that attempt proves.",minutes:{learning:6,suggestedAction:2,review:2},direction:{hook:"Did one rough attempt become another verdict about your whole life?",reason:{id:"turning-day-3-never-fact-check-reason",label:"Which part of your “never” claim does the last attempt support or contradict?",kind:"text",maxLength:160,optional:!0,suggestions:["One act happened; skill needs work","Cue missed; ability still untested","No attempt recorded yet"]},why:{id:"turning-day-3-why",label:"What would one honest practice unit serve this week?",kind:"text",maxLength:300,optional:!0}},idea:{paragraphs:["Belief about doing a particular task differs from your worth. One theory gives personal accomplishment an important role in that belief. It does not establish that every tiny act raises confidence or proves broad ability.","Return to your same unit. Describe the act precisely: “I drew one object; the outline needs work.” An imperfect attempt can meet your minimum while revealing a skill gap. Two minutes is a practical starting estimate, not an optimal dose established by research. Confidence can stay unchanged; record the act anyway."],example:{title:"Dana’s crooked handle",text:"After taking off her coat, Dana sketches one mug at the kitchen table. The handle looks crooked again, and she feels no more confident. Her note says, “One mug drawn; handle proportions need practice.” She chooses the same unit for her next available afternoon. One drawing does not prove she can design a poster."}},move:{invitation:"Keep your saved act and cue. Record its output and one limitation.",instructions:["Keep your action and minimum.","Under What will you look for, name output and a remaining limitation."],prompts:[],suggestions:{action:["Draw one everyday object","Write one usable sentence","Read one needed paragraph"],minimum:["Finish one small sketch","Write one useful sentence","Read one complete paragraph"],when:[{label:"Today",daysFromToday:0},{label:"Tomorrow",daysFromToday:1}],cue:["After my next cup of tea","At my next available break","After my next meal"],place:["At my kitchen table","At my usual work surface","In my accessible reading space"],minutes:[2,1,5],fallback:["Ask for help with the handle","Mark the fact needing a check","Mark the point needing an explanation"],observation:["Sketch output and one skill gap","Sentence output and one unchecked fact","Paragraph read and one unclear point"],bundles:[{action:"Draw one everyday object",minimum:"Finish one small sketch",cue:"After my next cup of tea",place:"At my kitchen table",fallback:"Ask for help with the handle",observation:"Sketch output and one skill gap",minutes:2},{action:"Write one usable sentence",minimum:"Write one useful sentence",cue:"At my next available break",place:"At my usual work surface",fallback:"Mark the fact needing a check",observation:"Sentence output and one unchecked fact",minutes:2},{action:"Read one needed paragraph",minimum:"Read one complete paragraph",cue:"After my next meal",place:"In my accessible reading space",fallback:"Mark the point needing an explanation",observation:"Paragraph read and one unclear point",minutes:2}]},suggested:{action:"Draw one everyday object",minimum:"Finish one small sketch",minutes:2,cueHint:"After my next cup of tea",placeHint:"At my kitchen table",obstacleHint:"One part of the output needs help",fallbackHint:"Ask for help with the handle",observationHint:"Sketch output and one skill gap"},accessibleAlternative:"Type, dictate, use adapted tools, or ask for assistance with your chosen unit.",stopRule:"Choose safe practice within your capacity. A poor result can call for support, adaptation, or a pause."},result:{question:"What actually happened with your chosen minimum?",observationPrompt:"What did you do, and what got in the way?"},judgment:{primary:{id:"turning-day-3-specific-record-decision",scenario:"Dana finished her promised mug sketch. Its handle is crooked, and she feels no more confident. She is choosing what to record.",question:"Which record best guides the next practice?",options:[{id:"repeat-before-assessing",text:"Record the finished sketch and repeat the same mug unchanged before deciding which detail needs practice.",feedback:"Repetition can help when the practice target is unclear. Dana can already name the crooked handle. Include that detail now so the next attempt can test a specific skill."},{id:"specific-evidence",text:"Record one completed mug sketch and the crooked handle, then choose the next practice opportunity.",feedback:"This names both the act and its limitation. Dana met the sketch minimum without proving broad drawing ability or requiring a confidence change. The next attempt can address the handle."},{id:"cue-reliability-from-once",text:"Record the finished sketch and keep this cue for next week because it worked today.",feedback:"Keeping a promising cue is reasonable as a trial. One completed attempt does not establish a reliable routine. Record the handle issue and test the cue again under the next conditions."}],bestOptionId:"specific-evidence"}},carry:{takeaway:"Name the behavior precisely. Let the remaining skill gap guide practice.",followUp:{questionId:"turning-day-3-return",question:"What did your finished unit show, and what still needs work?",observationPrompt:"What did you actually do or notice?",adjustmentPrompt:"What should stay or change at the next opportunity?"}},goDeeper:{sections:[{heading:"Task belief is a specific expectation",paragraphs:["Bandura’s 1977 article describes self-efficacy as an expectation about carrying out a particular behavior [T09]. It identifies personal accomplishments, observing others, encouragement, and physiological states as information for that expectation. The theory emphasizes personal mastery. It is not a trial establishing that every small action creates confidence or that mastery always outranks other support in every setting.","For this course, that distinction keeps the record useful. A completed sketch shows that you made that sketch under those conditions. It may reveal something about your tools, cue, or current skill. It does not measure your worth or establish that you can complete every future project.","If your work reveals missing knowledge, the next move can include instruction or help. If capacity or safety changes, adapt or pause. This is ordinary personal-growth practice, not treatment for intense anxiety or a test of character."]},{heading:"Small enough is not the same as complete",paragraphs:["James Clear’s two-minute rule is practitioner guidance, not a controlled finding that two minutes is optimal [T17]. A short entry can make a task approachable, but putting out a pencil is preparation. Drawing an object is drawing practice. Choose the minimum that actually serves your direction, and record preparation honestly when that is the appropriate act.","Progress monitoring improved goal attainment on average in Harkin and colleagues’ review of 138 randomized studies [T05]. Goals and methods varied. Physically recording progress was associated with larger effects in moderator analyses, but that does not validate ODA’s precise note format or require public sharing.","A short record can hold output and limitation together: one usable sentence written, but one fact still needs checking. Do not enlarge the claim because the step felt good or erase it because it felt disappointing. Choose the next unit from the evidence available."]}],sourceIds:["T09","T05","T17"]}},{schemaVersion:2,revision:2,id:"turning-day-4",courseId:"turning-day",locale:"en",title:"Stop making your next step hard to find",goal:"Test one setup change at the cue for your continuing useful-unit experiment.",minutes:{learning:6,suggestedAction:2,review:2},direction:{hook:"Was the tool you needed hidden while the distraction sat within reach?",reason:{id:"turning-day-4-reason",label:"Which setup demand can you remove without losing access?",kind:"text",maxLength:160,optional:!0,suggestions:["Find my tools at the cue","Keep needed contact available","Use a private record"]},why:{id:"turning-day-4-why",label:"Which setup demand can you remove without losing access?",kind:"text",maxLength:300,optional:!0}},idea:{paragraphs:["A cue includes an action’s setting, not just a phone reminder. Research describes how repeating a response in recurring contexts can make it more cue-driven. Preparing a needed item can reduce setup demands; it cannot remove effort or guarantee you remember.","Check your experiment’s last record. If finding tools was the obstacle, place them at your cue, then test your unit there. Keep necessary calls, care alerts, and accessibility tools available. Record privately if you prefer. Moving an object is setup; doing the unit tests it."],example:{title:"Dana keeps the phone reachable",text:"Dana’s last drawing opportunity disappeared while she searched for paper. She places a scrap pad and pencil beside her tea mug, then sketches the spoon after tea. Her phone stays reachable for family calls. She records one sketch privately. The setup worked this time; tomorrow’s shift may need a different cue."}},move:{invitation:"Keep your saved act, cue, and place. Test one setup change.",instructions:["Under What will you look for, name one material or access change.","Test your same minimum with that setup."],prompts:[],suggestions:{action:["Draw one everyday object","Write one usable sentence","Read one needed paragraph"],minimum:["Finish one small sketch","Write one useful sentence","Read one complete paragraph"],when:[{label:"Today",daysFromToday:0},{label:"Tomorrow",daysFromToday:1}],cue:["After my next cup of tea","When my planned break begins","After my next meal"],place:["At my kitchen table","At my usual work surface","In my accessible reading space"],minutes:[2,1,5],fallback:["Use an accessible backup pencil","Use my accessible backup writing tool","Open an accessible copy of the text"],observation:["Which pencil placement helped the sketch","Which document access change helped writing","Which text access change helped reading"],bundles:[{action:"Draw one everyday object",minimum:"Finish one small sketch",cue:"After my next cup of tea",place:"At my kitchen table",fallback:"Use an accessible backup pencil",observation:"Which pencil placement helped the sketch",minutes:2},{action:"Write one usable sentence",minimum:"Write one useful sentence",cue:"When my planned break begins",place:"At my usual work surface",fallback:"Use my accessible backup writing tool",observation:"Which document access change helped writing",minutes:2},{action:"Read one needed paragraph",minimum:"Read one complete paragraph",cue:"After my next meal",place:"In my accessible reading space",fallback:"Open an accessible copy of the text",observation:"Which text access change helped reading",minutes:2}]},suggested:{action:"Draw one everyday object",minimum:"Finish one small sketch",minutes:2,cueHint:"After my next cup of tea",placeHint:"At my kitchen table",obstacleHint:"Materials are hard to find or reach",fallbackHint:"Use an accessible backup pencil",observationHint:"Which pencil placement helped the sketch"},accessibleAlternative:"Type, dictate, use adapted tools, or ask for assistance with your chosen unit.",stopRule:"Keep emergency, care, and accessibility contact available when changing your setup."},result:{question:"What actually happened with your chosen minimum?",observationPrompt:"Which setup change did you test, and what did you actually do?"},judgment:{primary:{id:"turning-day-4-decision",scenario:"Dana lost a drawing opportunity searching for paper. She needs her phone reachable for family calls and prefers keeping her progress private.",question:"Which move fits these facts?",options:[{id:"mute-nonessential-alerts",text:"Mute nonessential alerts while keeping family calls, then rely on remembering where the paper is stored.",feedback:"This preserves needed contact and may reduce interruptions. It leaves the observed missing-materials problem unchanged. Put the drawing materials at the tea cue, then test the same sketch."},{id:"ready-tools",text:"Place paper beside her tea mug, preserve family calls, and test one sketch with a private record.",feedback:"This targets the observed setup problem without requiring disclosure or cutting off contact. Testing a sketch shows whether the ready tools helped at this particular opportunity."},{id:"private-reminder-first",text:"Set a private drawing reminder after tea and leave her paper in its usual storage place.",feedback:"A reminder may help with noticing the cue. Dana already notices tea, but cannot find the paper. Test the tool placement first, then consider a reminder if noticing becomes the problem."}],bestOptionId:"ready-tools"}},carry:{takeaway:"Test the setup against the real act. Keep privacy and necessary access.",followUp:{questionId:"turning-day-4-return",question:"Did the setup change help you use your cue and do the unit?",observationPrompt:"Which setup change helped or failed to help your saved act?",adjustmentPrompt:"What should stay or change at the next opportunity?"}},goDeeper:{sections:[{heading:"Context helps without doing the work for you",paragraphs:["Wood and Rünger’s review describes how repeated responses in recurring contexts can become cue-driven [T08]. Deliberate goals and habits can work together. This is an integrative review, not a trial proving that one particular object placement works for everyone. It does not establish a finite willpower battery or show that preparation removes executive difficulty.","Lally and colleagues followed everyday health behaviors for 84 days [T06]. Repetition in a consistent context accompanied increases in self-reported automaticity. There was no randomized no-practice control. This cannot supply a guaranteed timeline or prove the exact effect of placing a pencil near a mug.","ODA asks you to test a small environmental change because your last record identified a setup demand. Keep the action, cue, and minimum recognizable. That lets the next observation answer a practical question: were the needed materials available, and did you use them?"]},{heading:"Private recording is a full route",paragraphs:["Harkin and colleagues reviewed 138 randomized studies of progress monitoring [T05]. Monitoring interventions improved goal attainment on average. Physical recording and reporting were associated with larger effects in moderator analyses. Those comparisons do not prove that one friend is enough, that public disclosure is necessary, or that a private learner has chosen an inferior route.","A supportive check-in can be offered if you want it. You choose the person, the information, and the occasion. A factual private note remains a complete option here. There is no requirement to expose a goal, seek applause, or invite pressure from someone who is unsafe.","Likewise, changing phone placement must preserve necessary contact and accessibility. Target the observed hurdle: an item out of reach, a document difficult to find, or a nonessential alert. Record setup as setup, then observe what happened when you tried the same useful unit."]}],sourceIds:["T08","T05","T06"]}},{schemaVersion:2,revision:2,id:"turning-day-5",courseId:"turning-day",locale:"en",title:"Tonight, record the facts behind “I failed”",goal:"Review your experiment’s actual attempt and save one feasible next opportunity without rewriting its history.",minutes:{learning:6,suggestedAction:2,review:2},direction:{hook:"Calling today a failure? What does the record actually show?",reason:{id:"turning-day-5-reason",label:"What does your record show needs a change?",kind:"text",maxLength:160,optional:!0,suggestions:["Keep preparation and practice separate","Learn from a missed opening","Leave tomorrow in the plan"]},why:{id:"turning-day-5-why",label:"What does your record show needs a change?",kind:"text",maxLength:300,optional:!0}},idea:{paragraphs:["Put today’s act in the record and tomorrow’s intention in the plan. Research supports checking progress on average; a prepared tool does not show the practice happened. Preserve the minimum you committed to.","Name the act or gap in your experiment’s latest attempt, then choose one next opportunity. A study linked self-forgiveness with less later exam procrastination, without showing causation or validating a kind sentence. Review without blaming yourself or inventing success. If late review increases worry, choose an earlier slot."],example:{title:"Dana’s paper was ready",text:"Dana put paper beside her mug but stayed late at work. Her evening tea cue happened, and she did not draw. Before winding down, she records setup separately and drawing not yet. Tomorrow’s sketch after tea stays a plan. The review is brief; she still feels disappointed."}},move:{invitation:"Review your saved attempt. Keep the act; adjust one condition the record identifies.",instructions:["Record the actual attempt before editing its next occurrence.","Keep the action and minimum; change only the condition that did not fit."],prompts:[],suggestions:{action:["Draw one everyday object","Write one usable sentence","Read one needed paragraph"],minimum:["Finish one small sketch","Write one useful sentence","Read one complete paragraph"],when:[{label:"Today",daysFromToday:0},{label:"Tomorrow",daysFromToday:1}],cue:["At my next earlier tea break","At my next earlier work break","After my next meal"],place:["At my kitchen table","At my usual work surface","In my accessible reading space"],minutes:[2,1,5],fallback:["Rest; use tomorrow’s earlier tea break","Rest; use tomorrow’s earlier work break","Rest; read after tomorrow’s earlier meal"],observation:["Sketch output at the revised cue","Sentence output at the revised cue","Reading done at the revised cue"],bundles:[{action:"Draw one everyday object",minimum:"Finish one small sketch",cue:"At my next earlier tea break",place:"At my kitchen table",fallback:"Rest; use tomorrow’s earlier tea break",observation:"Sketch output at the revised cue",minutes:2},{action:"Write one usable sentence",minimum:"Write one useful sentence",cue:"At my next earlier work break",place:"At my usual work surface",fallback:"Rest; use tomorrow’s earlier work break",observation:"Sentence output at the revised cue",minutes:2},{action:"Read one needed paragraph",minimum:"Read one complete paragraph",cue:"After my next meal",place:"In my accessible reading space",fallback:"Rest; read after tomorrow’s earlier meal",observation:"Reading done at the revised cue",minutes:2}]},suggested:{action:"Draw one everyday object",minimum:"Finish one small sketch",minutes:2,cueHint:"At my next earlier tea break",placeHint:"At my kitchen table",obstacleHint:"Late work leaves too little capacity",fallbackHint:"Rest; use tomorrow’s earlier tea break",observationHint:"Sketch output at the revised cue"},accessibleAlternative:"Type, dictate, use adapted tools, or ask for assistance with your chosen unit.",stopRule:"If review increases worry or wakefulness, stop. Choose an earlier review slot or rest."},result:{question:"What actually happened with your chosen minimum?",observationPrompt:"What did you do, and what got in the way?"},judgment:{primary:{id:"turning-day-5-decision",scenario:"Dana did not draw her one-sketch minimum after late work. She had set out paper. Tomorrow has an earlier tea break; a longer weekend session is also possible.",question:"Which move fits these facts?",options:[{id:"same-cue-new-alert",text:"Record drawing not yet, keep the evening cue, and add an alert for that same time.",feedback:"This keeps the record honest. An alert addresses noticing, but Dana’s difficulty was late-work capacity. The earlier tea break lets her test the same minimum in a more feasible slot."},{id:"honest-change",text:"Record setup separately, report drawing not yet, and choose an earlier feasible cue for the same minimum.",feedback:"This preserves the promised minimum and reports what happened. Tomorrow’s intention stays a plan. Dana can change the cue without pretending setup was drawing or condemning the whole day."},{id:"weekend-session",text:"Record drawing not yet and move the experiment to a longer session on the weekend.",feedback:"A weekend session is a valid choice if it fits better. Here an earlier break is available tomorrow. Trying the same minimum there tests a smaller change before changing both timing and size."}],bestOptionId:"honest-change"}},carry:{takeaway:"Keep the past record honest. Change the next opportunity when the facts call for it.",followUp:{questionId:"turning-day-5-return",question:"Did the revised opportunity fit better, and what did you actually do?",observationPrompt:"What did you actually do or notice?",adjustmentPrompt:"What should stay or change at the next opportunity?"}},goDeeper:{sections:[{heading:"A fair review preserves responsibility",paragraphs:["Wohl and colleagues followed 119 first-year students around two midterms [T12]. Greater self-forgiveness for earlier procrastination was associated with less procrastination before the next exam. This was observational research in one course. It does not establish that forgiveness caused the change, that a scripted sentence changes behavior, or that self-criticism always produces avoidance.","You do not have to feel forgiving to make an accurate record. “I prepared the paper, but did not draw because work ran late” states two distinct facts. “Tomorrow I will draw after my first tea” states a plan. Preserve those categories even when the original attempt felt disappointing.","Progress monitoring has broader experimental support on average [T05], but ODA’s exact receipt and review flow have not been evaluated by that review. The purpose here is practical: choose the next condition from the information available, without turning a plan into proof."]},{heading:"The bedtime list finding has a narrow boundary",paragraphs:["Scullin and colleagues analyzed 57 healthy adults aged 18–30 during one laboratory night [T11]. Participants wrote with pen and paper for five minutes about future tasks or completed activities. The future-task group fell asleep sooner on average: 15.82 versus 25.09 minutes. The comparison was another writing task, not no writing. The study did not establish significantly more total sleep.","This result does not validate spoken suggestions, imagining tomorrow, or reviewing successes as sleep treatments. The five-minute paper task was a separate protocol. ODA’s short factual review and action plan are not that tested intervention. They do not promise sleep or require bedtime writing.","If review increases worry or keeps you awake, stop and choose an earlier opportunity. Rest can be the appropriate next step. Persistent sleep difficulties warrant professional assessment without waiting for this course to end. Keep the same useful-unit experiment; no new bedtime ritual is needed."]}],sourceIds:["T05","T12","T11"]}},{schemaVersion:2,revision:2,id:"turning-day-6",courseId:"turning-day",locale:"en",title:"Missed days? Build a week that fits",goal:"Use your existing records to choose a realistic next week for the same experiment, including safe pauses.",minutes:{learning:6,suggestedAction:2,review:2},direction:{hook:"What do your records reveal about the week you actually have?",reason:{id:"turning-day-6-reason",label:"Is this unit serving your direction at a workable cost?",kind:"text",maxLength:160,optional:!0,suggestions:["Keep the part that fits","Change the cue instead of compensating","Make room for recovery"]},why:{id:"turning-day-6-why",label:"Is this unit serving your direction at a workable cost?",kind:"text",maxLength:300,optional:!0}},idea:{paragraphs:["Compare planned opportunities, actual attempts, and useful output from your same experiment. A week tests fit; it does not complete a habit. The often-quoted 18–254 days came from modeled estimates in a study observing people for only 84 days.","Keep or shrink the unit, change its cue, or pause. One missed opportunity did not materially disrupt the process studied; no two-miss cutoff was established. Save one feasible next opportunity. ODA schedules its next-day return. Preserve the history, including gaps."],example:{title:"Dana’s week has gaps",text:"Dana planned five sketch opportunities and completed three. Both gaps followed late shifts. At Sunday tea, she keeps the one-object minimum and moves only the late-shift cue to Monday’s afternoon break. She saves that opportunity; ODA schedules Tuesday’s return. Three rough sketches remain three sketches, with two honest gaps."}},move:{invitation:"Keep your saved unit and workable cue. Adjust only the condition that blocked you.",instructions:["No record yet? Choose a first feasible trial.","Save the next opportunity; ODA schedules a return the following day."],prompts:[],suggestions:{action:["Draw one everyday object","Write one usable sentence","Read one needed paragraph"],minimum:["Finish one small sketch","Write one useful sentence","Read one complete paragraph"],when:[{label:"Today",daysFromToday:0},{label:"Tomorrow",daysFromToday:1}],cue:["At my next afternoon tea break","At my next available work break","After my next meal"],place:["At my kitchen table","At my usual work surface","In my accessible reading space"],minutes:[2,1,5],fallback:["Rest; use the next afternoon break","Use tomorrow’s reserved work break","Read after the next available meal"],observation:["Sketch output and cue availability","Sentence output and cue availability","Reading done and cue availability"],bundles:[{action:"Draw one everyday object",minimum:"Finish one small sketch",cue:"At my next afternoon tea break",place:"At my kitchen table",fallback:"Rest; use the next afternoon break",observation:"Sketch output and cue availability",minutes:2},{action:"Write one usable sentence",minimum:"Write one useful sentence",cue:"At my next available work break",place:"At my usual work surface",fallback:"Use tomorrow’s reserved work break",observation:"Sentence output and cue availability",minutes:2},{action:"Read one needed paragraph",minimum:"Read one complete paragraph",cue:"After my next meal",place:"In my accessible reading space",fallback:"Read after the next available meal",observation:"Reading done and cue availability",minutes:2}]},suggested:{action:"Draw one everyday object",minimum:"Finish one small sketch",minutes:2,cueHint:"At my next afternoon tea break",placeHint:"At my kitchen table",obstacleHint:"Late shifts block this practice slot",fallbackHint:"Rest; use the next afternoon break",observationHint:"Sketch output and cue availability"},accessibleAlternative:"Type, dictate, use adapted tools, or ask for assistance with your chosen unit.",stopRule:"Illness, exhaustion, care, or unsafe conditions can require consecutive pauses. Resume only when feasible."},result:{question:"What actually happened with your chosen minimum?",observationPrompt:"What did you do, and what got in the way?"},judgment:{primary:{id:"turning-day-6-observed-fit-decision",scenario:"Dana planned five sketches and made three. Both gaps followed late shifts. The one-object minimum worked at other opportunities.",question:"Which move fits these facts?",options:[{id:"shrink-before-moving",text:"Keep the late-shift cue, shrink each sketch to one outline, and compare the next week honestly.",feedback:"A smaller sketch could help if size were the barrier. Her existing minimum worked at other openings. First test a more available cue rather than changing the scope that already fit."},{id:"adjust-week",text:"Keep the one-object minimum, change the late-shift cue, and preserve all five opportunity records.",feedback:"This responds to the pattern while keeping the history honest. Dana can test another feasible cue. The three sketches count as output, not proof of a finished habit."},{id:"compensate-output",text:"Keep the late-shift cue and draw extra objects on free days to recover the missed output.",feedback:"Extra drawing may serve her goal if she chooses it, but it leaves the known cue conflict untouched. Fix the late-shift opportunity before adding compensatory load."}],bestOptionId:"adjust-week"}},carry:{takeaway:"Use the record to build the next week, including rest and safe pauses.",followUp:{questionId:"turning-day-6-return",question:"Did your chosen adjustment make the next opportunity workable?",observationPrompt:"What did you actually do or notice?",adjustmentPrompt:"What should stay or change at the next opportunity?"}},goDeeper:{sections:[{heading:"The habit number was modeled",paragraphs:["Lally and colleagues observed 96 volunteers for 84 days [T06]. Of those, 82 supplied adequate data, 62 had fitted curves, and 39 had good fits. Within those 39 curves, the estimated time to 95% of each person’s automaticity asymptote ranged from 18 to 254 days, with a median of 66. The 254-day endpoint was a model estimate extending beyond observation, not an observed finish.","The study relied on self-reports of everyday health behaviors and had no randomized control. One missed opportunity did not materially disrupt the examined process. That finding does not establish a threshold where two misses destroy a habit or make consecutive pauses a character failure.","This course’s week is a feasibility trial. Your drawing, learning, care, or recovery action may differ from the studied behaviors. Use actual opportunities and output to judge fit, without treating a streak as a validated transformation measure."]},{heading:"Consolidate the experiment you already have",paragraphs:["A 2024 review covered 20 health-behavior habit studies with 2,601 participants [T07]. Only four studies supplied formation-time estimates, and eleven studies had high bias risk. Different definitions and methods limit a single timetable. Pre–post changes in habit strength do not establish a controlled treatment effect or tell you when your chosen behavior will become automatic.","Progress-monitoring interventions improved goal attainment on average across 138 randomized studies [T05]. Here, use your existing records instead of adding another ritual. Count the opportunities you actually planned, attempts you reported, and useful units produced separately. A missing report stays unknown until you say what happened.","Choose whether the experiment still serves your direction. Repeat a workable unit, change one observed problem, seek support, rest, or stop. Saving one next opportunity books its next-day ODA return. A weekly comparison is an optional private calendar choice, not a second booking here. Learning completion is separate from carrying out the plan."]}],sourceIds:["T06","T07","T05"]}}],c=[{id:"1676475382103-54041209cf6c",alt:"Woman writing notes in a notebook beside a coffee cup"},{id:"1740815897057-a93a8cf98a70",alt:"Woman walking along a tree-lined path in a park"},{id:"1758854486305-eb7621f1e2e4",alt:"Person working at a table beside a large arched window"},{id:"1756312177615-e153c9db507d",alt:"Woman talking on the phone in a kitchen"},{id:"1768219565623-501f93ae384b",alt:"Desk lit by a lamp in the evening"},{id:"1529651737248-dad5e287768e",alt:"Pen resting on a planner calendar"}],s=[0,1,1,1,1,1],l={id:"turning-day",title:"Still waiting for Monday? Make one real start",subtitle:"Six lessons. Try one useful change, learn what blocks it, and build a week that fits.",description:"Take one useful step toward a life direction you choose. Carry the same experiment through six lessons: a first act, an obstacle response, a precise record, a tested setup, an honest review, and a workable next week.",scope:"Personal growth training for adults. It is not therapy, diagnosis or treatment, and it does not promise that your life will change in a single day. Do not stop any treatment or medication without talking to your doctor. If you are dealing with intense anxiety, low mood or distress that makes daily life hard, please see a health professional; if you have thoughts of harming yourself or are in immediate danger, call your local emergency number.",outcome:"A tested or paused change, a factual record, and a feasible next date.",photo:{id:"1570821805833-1103c43f9c1d",alt:"Sunbeams falling across a path between trees"},lessons:r.map((e,n)=>{const t=e.judgment.primary,i=t.options.find(a=>a.id===t.bestOptionId),o=t.options.filter(a=>a.id!==t.bestOptionId);return o.splice(s[n],0,i),{id:e.id,schemaVersion:2,v2:e,title:e.title,minutes:e.minutes.learning,goal:e.goal,reading:e.idea.paragraphs,practice:[...e.move.instructions,"Return here and record what actually happened."].slice(0,3),reflection:e.direction.reason.label,question:`${t.scenario} ${t.question}`,options:o.map(a=>a.text),correct:s[n],feedback:i.feedback,takeaway:e.carry.takeaway,sources:e.goDeeper.sourceIds,deeper:e.goDeeper.sections,example:e.idea.example,photo:c[n]}})};export{l as COURSE,d as SOURCES,r as TURNING_DAY_LESSONS_V2};
